INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('social-media-jugendliche-goeg-analyse-psyche-youthvoice','Social Media und Jugendliche: GÖG-Analyse zeigt Risiken für die Psyche','Nicht die Dauer, sondern die Art der Nutzung zählt: Eine GÖG-Analyse zeigt Risiken von Social Media für Jugendliche. Bis Februar 2027 können 14- bis 25-Jährige mitreden.','Social Media und Jugendliche: Wie viel Zeit am Smartphone schadet, hängt laut einer neuen Analyse der Gesundheit Österreich GmbH (GÖG) weniger von der Dauer als von der Art der Nutzung ab. Das Gesundheitsstaatssekretariat hat die Ergebnisse am Donnerstag in Wien vorgestellt und gleichzeitig einen Beteiligungsprozess gestartet: Junge Menschen zwischen 14 und 25 Jahren sollen bis Februar 2027 eigene Vorschläge einbringen, wie ihr psychisches Wohlbefinden im Umgang mit Plattformen besser geschützt werden kann.

Hintergrund ist das geplante Social-Media-Verbot für unter 14-Jährige. Die EU-Kommission hat die Stillhaltefrist für den österreichischen Entwurf um ein Jahr verlängert, das Gesetz könnte damit frühestens Ende Juli 2027 in Kraft treten, ohne ein Vertragsverletzungsverfahren zu riskieren.

## Was die GÖG-Analyse zu Social Media und Psyche zeigt

Für die Übersichtsarbeit hat die GÖG 145 wissenschaftliche Quellen ausgewertet. Die zentrale Aussage: Eine lange Bildschirmzeit ist für sich genommen nicht automatisch schädlich. Austausch mit Freundinnen, Freunden oder Communities kann sogar positiv wirken. Entscheidend ist, womit die Zeit verbracht wird.

Als problematisch gelten vor allem folgende Muster:

- stundenlanges passives Scrollen durch emotional aufgeladene Inhalte, häufig als Doomscrolling bezeichnet
- das zwanghafte Konsumieren negativer Nachrichten
- der ständige Vergleich mit geschönten, idealisierten Körperbildern

Eine ungünstige Nutzung wird in der Forschung mit Depressionen, Schlafmangel und sozialem Rückzug in Verbindung gebracht.

## Wie viele Jugendliche betroffen sind

Laut den präsentierten Zahlen zeigen in Österreich rund 10 Prozent der Mädchen und etwa 7 Prozent der Burschen ein problematisches Nutzungsverhalten. Besonders deutlich ist der Druck beim Thema Aussehen: 45 Prozent der 16- bis 25-Jährigen geben an, dass Inhalte in sozialen Netzwerken ihnen das Gefühl vermitteln, ihren Körper optimieren zu müssen. Diese Zahl hob GÖG-Expertin Gerlinde Rohrauer-Näf bei der Präsentation hervor.

## YouthVOICE: So können Jugendliche mitreden

Kern des neuen Prozesses ist die Online-Plattform YouthVOICE. Dort können Jugendliche und junge Erwachsene zwischen 14 und 25 Jahren bis Februar 2027 Ideen einreichen. Gefragt wird, was Politik, Plattformbetreiber, Schulen und Eltern konkret tun könnten, damit soziale Medien und auch Künstliche Intelligenz der psychischen Gesundheit weniger schaden.

Der weitere Fahrplan sieht so aus:

1. Sammlung der Vorschläge online bis Februar 2027
2. drei Jugendforen im ersten Halbjahr 2027 in Wien, Graz und Innsbruck
3. Übergabe der Ergebnisse an die Politik im Juni 2027

Zusätzlich sind Workshops sowie sogenannte Botschafterinnen und Botschafter für digitales Wohlbefinden geplant. Sie sollen das Bewusstsein für den Zusammenhang zwischen Online-Verhalten und psychosozialer Gesundheit stärken.

## Kritik an der Bauweise der Plattformen

Die Bundesjugendvertretung sitzt mit am Tisch. Deren Vorsitzender Moritz Mittermann sieht das Kernproblem weniger im Gebrauch der Apps an sich als in deren Gestaltung. Mechanismen wie Likes oder sogenannte Streaks, die tägliche Nutzung belohnen, verglich er mit Reizen aus dem Glücksspiel.

## Wie es mit dem Social-Media-Verbot weitergeht

Der Entwurf sieht ein Mindestalter von 14 Jahren für bestimmte Plattformen vor und soll über eine Novelle des Audiovisuellen Mediendienste-Gesetzes umgesetzt werden. Die EU-Kommission begründet den Aufschub mit dem geplanten europäischen Kids Act, der einheitliche Regeln zum Schutz Minderjähriger bringen soll. Vizekanzler und Medienminister Andreas Babler (SPÖ) kritisierte die Verzögerung und kündigte an, die Umsetzung vorzubereiten, sobald die Fristen abgelaufen sind. Staatssekretär Alexander Pröll (ÖVP) bezeichnete die Blockade aus Brüssel als inakzeptabel. Die NEOS begrüßen hingegen eine europäische Lösung.

Für Eltern und Jugendliche bedeutet das: Bis auf Weiteres gibt es keine gesetzliche Altersgrenze, die Diskussion über gesunde Nutzung läuft aber bereits jetzt. Wer zwischen 14 und 25 ist, kann sich über YouthVOICE direkt einbringen.','gesundheit','Psyche',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/social-media-jugendliche-goeg-analyse-psyche-youthvoice.webp','Salzburger Nachrichten / APA','https://www.sn.at/panorama/oesterreich/jugend-soll-bei-social-media-massnahmen-fuer-teenager-mitreden-art-681084','published','2026-10-31T06:55:00.000Z','2026-11-01T11:53:57.184Z','Social Media und Jugendliche: Risiken für die Psyche','Social Media und Jugendliche: GÖG-Analyse nennt Doomscrolling und Körperdruck als Risiko. Jetzt bis Februar 2027 über YouthVOICE mitreden.','Social Media Jugendliche','["Social Media Jugendliche","Social Media Psyche","Social-Media-Verbot Österreich","GÖG Analyse Social Media","YouthVOICE","Doomscrolling","psychische Gesundheit Jugendliche","Social Media Mindestalter 14","Königsberger-Ludwig Social Media"]','Social Media und Jugendliche: Jugendlicher mit Smartphone auf einer Parkbank im Herbst','Teenager sitting on a bench in an Austrian city park in autumn, seen from behind and slightly to the side, holding a smartphone with glowing screen, fallen yellow leaves, soft morning light, Vienna-style historic buildings blurred in background, no text, no logos, no readable signs','[{"q":"Wie viele Jugendliche in Österreich nutzen Social Media problematisch?","a":"Laut GÖG zeigen rund 10 Prozent der Mädchen und etwa 7 Prozent der Burschen ein problematisches Nutzungsverhalten."},{"q":"Wie können Jugendliche bei YouthVOICE mitmachen?","a":"14- bis 25-Jährige können bis Februar 2027 online Vorschläge einreichen. 2027 folgen Jugendforen in Wien, Graz und Innsbruck, Ergebnisse gibt es im Juni."},{"q":"Ab wann gilt das Social-Media-Verbot für unter 14-Jährige?","a":"Nach dem EU-Aufschub frühestens ab Ende Juli 2027. Bis dahin gibt es keine gesetzliche Altersgrenze."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
